int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<vector<long long>> d(h, vector<long long>(w));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cin >> d[i][j];
        }
    }

    const long long INF = 1000000000;
    vector<long long> need(w + 1, INF);
    need[w - 1] = 1;
    for (int i = (int)h - 1; i >= 0; i--) {
        vector<long long> next(w + 1, INF);
        for (int j = (int)w - 1; j >= 0; j--) {
            long long best = min(need[j], next[j + 1]);
            next[j] = max(1LL, best - d[i][j]);
        }
        need = next;
    }
    cout << need[0] << "\n";

    return 0;
}

